<script setup lang="ts">import {computed} from 'vue';import {ArrowUpRight,Plus} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import RunSummary from '../components/RunSummary.vue';import SurvivalPlot from '../components/SurvivalPlot.vue';import Notice from '../components/common/Notice.vue';import {percent} from '../utils/format';const s=useResearchData(),auth=useAuth(),run=computed(()=>s.runs.find(r=>r.status==='completed'));const n=computed(()=>s.cohorts.reduce((sum,c)=>sum+c.specimen_count,0)),censored=computed(()=>s.cohorts.reduce((sum,c)=>sum+c.censored,0));</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">RESEARCH DESK / 01</p><h1>研究总览<span>从已知的工作时间，读出耐久分布。</span></h1></div><RouterLink v-if="auth.user?.role!=='viewer'" class="outline" to="/configure"><Plus :size="16"/>建立比较</RouterLink></div><Notice :message="s.error" @retry="s.refresh"/><div class="overview-grid"><section class="evidence-sheet"><div class="section-top"><span class="eyebrow">LATEST OBSERVATION / 最新研究</span><RouterLink to="/results">阅读结果 <ArrowUpRight :size="14"/></RouterLink></div><template v-if="run"><RunSummary :run="run"/><SurvivalPlot :result="run.result"/></template><p v-else class="empty">尚无研究，先选择两批工艺建立比较。</p></section><aside class="archive-note"><span class="eyebrow">READING NOTE / 001</span><h2>没有观察到失效，<br/>并不意味着<br/>永不失效。</h2><p>删失保留“至少已工作这么久”的信息。尾部在险试件少时，曲线与中位时间都要谨慎解释。</p><div class="note-divider"/><div class="count"><b>{{n}}</b><span>独立灯带试件<br/>{{n?percent(censored/n):'—'}} 右删失</span></div><RouterLink to="/cohorts">打开试件档案 →</RouterLink></aside></div><div class="section-heading"><h2>两批封装工艺</h2><span>zh-lightstrip-followup.csv</span></div><div class="cohort-row"><RouterLink v-for="c in s.cohorts" :key="c.id" :to="'/cohorts?cohort='+c.id"><span class="eyebrow">{{c.code}} / {{c.process}}</span><h3>{{c.name}}</h3><p>{{c.specimen_count}} 件 · {{c.events}} 失效事件 · {{c.censored}} 右删失</p><span>查阅随访 →</span></RouterLink></div></div></template>
